package org.sigf.services;
import java.sql.*;import java.math.*;import java.time.LocalDate;import java.util.*;import org.sigf.config.*;import org.sigf.domain.*;import org.sigf.security.*;import org.sigf.repositories.*;
public final class SalesService {
 private final Database db; public SalesService(Database db){this.db=db;}
 private static void requireNio(Connection c)throws SQLException{try(Statement q=c.createStatement();ResultSet r=q.executeQuery("select value from setting where key='currency'")){if(!r.next()||!r.getString(1).equals("NIO"))throw new IllegalStateException("Configure la moneda NIO antes de vender; los importes anteriores no se convierten automáticamente");}}
 private static void required(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Complete los campos obligatorios");}
 public void voidSale(Security.User u,long sale,String reason)throws SQLException{u.admin();required(reason);try(Connection c=db.connection()){c.setAutoCommit(false);try{Security.verify(c,u,true);try(PreparedStatement lock=c.prepareStatement("select p.id from product p where p.id in (select product_id from sale_line where sale_id=?) order by p.id for update")){lock.setLong(1,sale);lock.executeQuery().close();}try(PreparedStatement s=c.prepareStatement("update sale set status='VOID',voided_at=now(),voided_by=?,void_reason=? where id=? and status='CONFIRMED'")){s.setLong(1,u.id());s.setString(2,reason);s.setLong(3,sale);if(s.executeUpdate()!=1)throw new IllegalArgumentException("Venta inexistente o ya anulada");}try(PreparedStatement s=c.prepareStatement("select batch_id,quantity from sale_line where sale_id=? order by batch_id")){s.setLong(1,sale);try(ResultSet r=s.executeQuery()){while(r.next()){long batch=r.getLong(1);int n=r.getInt(2);try(PreparedStatement q=c.prepareStatement("update batch set quantity=quantity+? where id=?")){q.setInt(1,n);q.setLong(2,batch);q.executeUpdate();}StockMovementRepository.write(c,batch,n,"SALE_VOID",sale,u.id());}}}AuditRepository.write(c,u,"SALE_VOID",sale+": "+reason);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public String receipt(long sale)throws SQLException{return new ReceiptRepository(db).receipt(sale);}
 public Receipt sell(Security.User u,List<CartItem> items,Long customer,String method,UUID request)throws SQLException{return sell(u,items,customer,method,request,null);}
 public Receipt quote(List<CartItem> items)throws SQLException{return quoteDetailed(items).totals();}
 public SaleQuote quoteDetailed(List<CartItem> items)throws SQLException {if(items.isEmpty())throw new IllegalArgumentException("El carrito está vacío");TreeMap<Long,Integer> totals=new TreeMap<>();for(CartItem i:items){if(i.quantity()<=0)throw new IllegalArgumentException("Cantidad inválida");totals.merge(i.productId(),i.quantity(),Math::addExact);}BigDecimal sub=BigDecimal.ZERO,tax=BigDecimal.ZERO;List<QuoteLine> lines=new ArrayList<>();try(Connection c=db.connection()){for(var e:totals.entrySet()){try(PreparedStatement s=c.prepareStatement("select sale_price,tax_rate from product where id=? and active")){s.setLong(1,e.getKey());try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("Producto inactivo o inexistente");BigDecimal price=r.getBigDecimal(1),rate=r.getBigDecimal(2);if(rate==null)throw new IllegalArgumentException("Producto sin clasificación de IVA: "+e.getKey());BigDecimal amount=price.multiply(BigDecimal.valueOf(e.getValue()));sub=sub.add(amount);tax=tax.add(amount.multiply(rate).setScale(2,RoundingMode.HALF_UP));lines.add(new QuoteLine(e.getKey(),e.getValue(),price,rate));}}}return new SaleQuote(new Receipt(0,sub,tax,sub.add(tax)),List.copyOf(lines));}}
 public Receipt sell(Security.User u,List<CartItem> items,Long customer,String method,UUID request,BigDecimal expectedTotal)throws SQLException{return sell(u,items,customer,method,request,expectedTotal,null);}
 public Receipt sell(Security.User u,List<CartItem> items,Long customer,String method,UUID request,BigDecimal expectedTotal,List<QuoteLine> expectedLines)throws SQLException{
  if(items.isEmpty())throw new IllegalArgumentException("El carrito está vacío");if(!Set.of("CASH","CARD","TRANSFER").contains(method))throw new IllegalArgumentException("Forma de pago inválida");TreeMap<Long,Integer> totals=new TreeMap<>();for(CartItem item:items){if(item.quantity()<=0)throw new IllegalArgumentException("Cantidad inválida");totals.merge(item.productId(),item.quantity(),Math::addExact);}
  try(Connection c=db.connection()){c.setAutoCommit(false);try{
   Security.verify(c,u,false);requireNio(c);try(PreparedStatement s=c.prepareStatement("select pg_advisory_xact_lock(hashtextextended(?,0))")){s.setString(1,request.toString());s.execute();}
   try(PreparedStatement s=c.prepareStatement("select id,subtotal,tax,total,created_by from sale where request_id=?")){s.setObject(1,request);try(ResultSet r=s.executeQuery()){if(r.next()){if(r.getLong(5)!=u.id()&&!u.role().equals("ADMIN"))throw new SecurityException("Solicitud ajena");Receipt receipt=new Receipt(r.getLong(1),r.getBigDecimal(2),r.getBigDecimal(3),r.getBigDecimal(4));c.commit();return receipt;}}}
   try(PreparedStatement s=c.prepareStatement("select acknowledged_at from sale_request where request_id=?")){s.setObject(1,request);try(ResultSet r=s.executeQuery()){if(r.next()&&r.getTimestamp(1)!=null)throw new IllegalArgumentException("La solicitud fue cancelada");}}
   Map<Long,QuoteLine> expected=new HashMap<>();if(expectedLines!=null){for(QuoteLine line:expectedLines){if(line.price()==null||line.taxRate()==null||expected.put(line.productId(),line)!=null)throw new IllegalArgumentException("Solicitud anterior sin detalle de precios; cancélela y vuelva a cotizar");}if(expected.size()!=totals.size())throw new IllegalArgumentException("Solicitud anterior sin detalle de precios; cancélela y vuelva a cotizar");}Map<Long,BigDecimal> prices=new HashMap<>(),rates=new HashMap<>();Map<Long,String> productNames=new HashMap<>();BigDecimal subtotal=BigDecimal.ZERO,tax=BigDecimal.ZERO;
   for(var e:totals.entrySet()){try(PreparedStatement s=c.prepareStatement("select sale_price,tax_rate,name from product where id=? and active for update")){s.setLong(1,e.getKey());try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("Producto inactivo o inexistente: "+e.getKey());BigDecimal price=r.getBigDecimal(1);prices.put(e.getKey(),price);productNames.put(e.getKey(),r.getString(3));BigDecimal rate=r.getBigDecimal(2);if(rate==null)throw new IllegalArgumentException("Producto sin clasificación de IVA: "+e.getKey());if(expectedLines!=null){QuoteLine expectedLine=expected.get(e.getKey());if(expectedLine==null||expectedLine.quantity()!=e.getValue()||expectedLine.price().compareTo(price)!=0||expectedLine.taxRate().compareTo(rate)!=0)throw new IllegalArgumentException("Cambió un precio o IVA; cancele la solicitud y vuelva a cotizar");}rates.put(e.getKey(),rate);BigDecimal amount=price.multiply(BigDecimal.valueOf(e.getValue()));subtotal=subtotal.add(amount);tax=tax.add(amount.multiply(rate).setScale(2,RoundingMode.HALF_UP));}}}
   BigDecimal total=subtotal.add(tax);if(expectedTotal!=null && total.compareTo(expectedTotal)!=0)throw new IllegalArgumentException("Los precios o impuestos cambiaron; revise nuevamente el total");long sale;
   try(PreparedStatement s=c.prepareStatement("insert into sale(request_id,customer_id,created_by,subtotal,tax,total) values(?,?,?,?,?,?) returning id")){s.setObject(1,request);if(customer==null)s.setNull(2,Types.BIGINT);else s.setLong(2,customer);s.setLong(3,u.id());s.setBigDecimal(4,subtotal);s.setBigDecimal(5,tax);s.setBigDecimal(6,total);try(ResultSet r=s.executeQuery()){r.next();sale=r.getLong(1);}}
   try(PreparedStatement snap=c.prepareStatement("insert into sale_receipt_snapshot(sale_id,pharmacy_name,legal_name,ruc,address,phone,email,customer_name,currency,customer_ruc) values (?,coalesce((select pharmacy_name from pharmacy_profile where id=1),(select value from setting where key='pharmacy_name'),'Farmacia'),coalesce((select legal_name from pharmacy_profile where id=1),''),coalesce((select ruc from pharmacy_profile where id=1),''),coalesce((select address from pharmacy_profile where id=1),''),coalesce((select phone from pharmacy_profile where id=1),''),coalesce((select email from pharmacy_profile where id=1),''),coalesce((select name from customer where id=?),'Consumidor final'),coalesce((select value from setting where key='currency'),'NIO'),coalesce((select ruc from customer where id=?),''))")){snap.setLong(1,sale);if(customer==null){snap.setNull(2,Types.BIGINT);snap.setNull(3,Types.BIGINT);}else{snap.setLong(2,customer);snap.setLong(3,customer);}snap.executeUpdate();}
   for(var e:totals.entrySet()){int left=e.getValue();try(PreparedStatement s=c.prepareStatement("select id,quantity from batch where product_id=? and quantity>0 and not blocked and expires_on>=current_date order by expires_on,id for update")){s.setLong(1,e.getKey());try(ResultSet r=s.executeQuery()){while(left>0&&r.next()){long batch=r.getLong(1);int n=Math.min(left,r.getInt(2));try(PreparedStatement q=c.prepareStatement("update batch set quantity=quantity-? where id=?")){q.setInt(1,n);q.setLong(2,batch);q.executeUpdate();}try(PreparedStatement q=c.prepareStatement("insert into sale_line(sale_id,product_id,batch_id,quantity,unit_price,tax_rate,product_name_snapshot) values(?,?,?,?,?,?,?)")){q.setLong(1,sale);q.setLong(2,e.getKey());q.setLong(3,batch);q.setInt(4,n);q.setBigDecimal(5,prices.get(e.getKey()));q.setBigDecimal(6,rates.get(e.getKey()));q.setString(7,productNames.get(e.getKey()));q.executeUpdate();}StockMovementRepository.write(c,batch,-n,"SALE",sale,u.id());left-=n;}}}if(left>0)throw new IllegalArgumentException("Existencias vendibles insuficientes para producto "+e.getKey());}
   String series;long documentNumber;try(Statement q=c.createStatement();ResultSet r=q.executeQuery("update internal_series set next_number=next_number+1 where id=1 returning code,next_number-1")){if(!r.next())throw new IllegalStateException("Falta la serie interna");series=r.getString(1);documentNumber=r.getLong(2);}try(PreparedStatement doc=c.prepareStatement("insert into internal_document(sale_id,series,number) values(?,?,?)")){doc.setLong(1,sale);doc.setString(2,series);doc.setLong(3,documentNumber);doc.executeUpdate();}
   try(PreparedStatement s=c.prepareStatement("insert into payment(sale_id,method,amount,received_amount,change_amount) values(?,?,?,?,?)")){s.setLong(1,sale);s.setString(2,method);s.setBigDecimal(3,total);BigDecimal received=null;try(PreparedStatement cash=c.prepareStatement("select received_amount from sale_request where request_id=?")){cash.setObject(1,request);try(ResultSet r=cash.executeQuery()){if(r.next())received=r.getBigDecimal(1);}}if(received!=null&&(!method.equals("CASH")||received.compareTo(total)<0))throw new IllegalArgumentException("Recibido inválido");s.setBigDecimal(4,received);s.setBigDecimal(5,received==null?null:received.subtract(total));s.executeUpdate();}c.commit();return new Receipt(sale,subtotal,tax,total);
  }catch(Exception ex){c.rollback();throw ex;}}
 }
}
